INSERT INTO organizations (id, name, slug, subscription_tier)
INSERT INTO compliance_controls (organization_id, framework, control_code, category, title, description, evaluation_type, mapped_rule_categories, status, evidence_notes)
VALUES
('11111111-1111-1111-1111-111111111111', 'ISO_27001', 'A.5.15', 'Organizational Controls', 'Access Control Policy & Enforcement', 'Rules to control physical and logical access to information and other associated assets.', 'AUTOMATED', '["IAM", "AUTH", "RBAC"]', 'PASSING', 'Verified via Platform RBAC enforcement and Cloud IAM least-privilege rules.'),
('11111111-1111-1111-1111-111111111111', 'ISO_27001', 'A.8.2', 'Technological Controls', 'Privileged Access Rights', 'The allocation and use of privileged access rights shall be restricted and managed.', 'AUTOMATED', '["IAM", "PRIVILEGED_ACCESS"]', 'PASSING', 'Evaluated against wildcard IAM policy checks and root account usage rules.'),
('11111111-1111-1111-1111-111111111111', 'ISO_27001', 'A.8.5', 'Technological Controls', 'Secure Authentication', 'Secure authentication technologies and procedures shall be implemented based on access restrictions.', 'AUTOMATED', '["MFA", "AUTH", "BRUTE_FORCE"]', 'PASSING', 'Evaluated against IAM MFA status and platform brute-force protection controls.'),
('11111111-1111-1111-1111-111111111111', 'ISO_27001', 'A.8.8', 'Technological Controls', 'Management of Technical Vulnerabilities', 'Information about technical vulnerabilities of information systems in use shall be obtained and evaluated.', 'AUTOMATED', '["WEB_SCAN", "DEPENDENCY_CVE", "API_SECURITY"]', 'PASSING', 'Evaluated continuously via Web, API, and OSV Dependency Vulnerability Scanner.'),
('11111111-1111-1111-1111-111111111111', 'ISO_27001', 'A.8.15', 'Technological Controls', 'Logging and Audit Trails', 'Logs that record activities, exceptions, faults and other relevant Security events shall be produced and stored.', 'AUTOMATED', '["LOGGING", "AUDIT", "CLOUDTRAIL"]', 'PASSING', 'Verified via CloudTrail/Audit log checks and immutable platform audit_logs table.'),
('11111111-1111-1111-1111-111111111111', 'ISO_27001', 'A.8.16', 'Technological Controls', 'Monitoring Activities', 'Networks, systems and applications shall be monitored for anomalous behaviour and appropriate actions taken.', 'AUTOMATED', '["THREAT_MONITORING", "AI_SECURITY"]', 'PASSING', 'Verified via real-time Threat Detection Engine and AI Application Guardrail monitor.'),
('11111111-1111-1111-1111-111111111111', 'ISO_27001', 'A.8.20', 'Technological Controls', 'Networks Security', 'Networks and network devices shall be secured, managed and controlled to protect information in systems.', 'AUTOMATED', '["NETWORK", "PORT_SCAN", "FIREWALL"]', 'PASSING', 'Evaluated against Security Group open port rules and Nmap port exposure scans.'),
('11111111-1111-1111-1111-111111111111', 'ISO_27001', 'A.8.24', 'Technological Controls', 'Use of Cryptography', 'Rules for the effective use of cryptography, including cryptographic key management, shall be defined and implemented.', 'AUTOMATED', '["ENCRYPTION", "SSL_TLS", "STORAGE"]', 'PASSING', 'Evaluated against S3/EBS/RDS encryption at rest and SSL/TLS certificate & cipher checks.')
INSERT INTO compliance_controls (organization_id, framework, control_code, category, title, description, evaluation_type, mapped_rule_categories, status, evidence_notes)
VALUES
('11111111-1111-1111-1111-111111111111', 'SOC_2', 'CC6.1', 'Logical and Physical Access Controls', 'Logical Access Security Software and Infrastructure', 'The entity implements logical access security software, infrastructure, and architectures over protected information assets.', 'AUTOMATED', '["IAM", "STORAGE", "ENCRYPTION", "AUTH"]', 'PASSING', 'Mapped to Cloud Storage Public Access blocks, IAM policies, and encryption checks.'),
('11111111-1111-1111-1111-111111111111', 'SOC_2', 'CC6.2', 'Logical and Physical Access Controls', 'User Registration and Credential Authorization', 'Prior to issuing system credentials and granting system access, the entity registers and authorizes new internal and external users.', 'AUTOMATED', '["MFA", "RBAC", "IAM"]', 'PASSING', 'Mapped to User RBAC auditing and Cloud IAM MFA checks.'),
('11111111-1111-1111-1111-111111111111', 'SOC_2', 'CC6.6', 'Logical and Physical Access Controls', 'Boundary Protection and Network Segmentation', 'The entity implements logical access security measures to protect against threats from sources outside its system boundaries.', 'AUTOMATED', '["NETWORK", "PORT_SCAN", "HTTP_HEADERS", "FIREWALL"]', 'PASSING', 'Mapped to Cloud Security Groups, WAF blocks, HTTP Security Headers, and Port Scans.'),
('11111111-1111-1111-1111-111111111111', 'SOC_2', 'CC6.7', 'Logical and Physical Access Controls', 'Data Transmission Encryption', 'The entity restricts the transmission, movement, and removal of information to authorized internal and external users and processes.', 'AUTOMATED', '["SSL_TLS", "HTTP_HEADERS"]', 'PASSING', 'Mapped to SSL/TLS Certificate validity, TLS protocol version, and HSTS checks.'),
('11111111-1111-1111-1111-111111111111', 'SOC_2', 'CC7.1', 'System Operations', 'Vulnerability and Configuration Management', 'To meet its objectives, the entity uses detection and monitoring procedures to identify changes to configurations that result in new vulnerabilities.', 'AUTOMATED', '["WEB_SCAN", "DEPENDENCY_CVE", "CLOUD_CSPM"]', 'PASSING', 'Mapped to continuous CSPM checks, Web/API scanning, and OSV dependency scanning.'),
('11111111-1111-1111-1111-111111111111', 'SOC_2', 'CC7.2', 'System Operations', 'Security Event Monitoring and Anomaly Analysis', 'The entity monitors system components and the operation of those components for anomalies that are indicative of malicious acts.', 'AUTOMATED', '["THREAT_MONITORING", "LOGGING", "AI_SECURITY"]', 'PASSING', 'Mapped to Threat Detection Engine alerts, Audit Logs, and AI Guardrail monitoring.'),
('11111111-1111-1111-1111-111111111111', 'SOC_2', 'CC7.3', 'System Operations', 'Incident Evaluation and Automated Containment', 'The entity evaluates security events to determine whether they could or have resulted in a failure of the entity to meet its objectives.', 'AUTOMATED', '["INCIDENT_RESPONSE", "FIREWALL"]', 'PASSING', 'Mapped to Attack Prevention & Automated Response approval workflows.')
